<script module lang="ts">
/**
 * Progress through an ordered flow (`design/components/stepper.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stepper.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/stepper.module.css'

export type StepperOrientation = NonNullable<StepperProps['orientation']>

export interface Step {
  label: string
  description?: string
  error?: boolean
}

export type StepperSpokenState = 'completed' | 'active' | 'upcoming' | 'error'

export type StepperSpoken = (step: {
  position: number
  count: number
  state: StepperSpokenState
}) => string

export interface StepperProps {
  /**
   * 0-based. Everything before it is completed, everything after it upcoming.
   */
  activeIndex: number
  /**
   * Renders completed steps as buttons. Active and upcoming stay static.
   */
  onStepSelect?: (index: number) => void
  orientation?: 'horizontal' | 'vertical'
  /**
   * Omit for the generic English sentence; localized hosts pass their own.
   */
  spoken?: StepperSpoken
  /**
   * Two to five; the spec says a flow with six steps needs a redesign.
   */
  steps: Step[]
}
</script>

<script lang="ts">
let {
  activeIndex,
  onStepSelect,
  orientation = 'horizontal',
  spoken = ({ position, count, state }: Parameters<StepperSpoken>[0]) =>
    `step ${position} of ${count}, ${{ completed: 'completed', active: 'current', upcoming: 'not started', error: 'error' }[state]}`,
  steps,
}: StepperProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get stepSelect() {
    return onStepSelect !== undefined
  },
}
let root = $state<HTMLElement | null>(null)
const rows = $derived(
  steps.map((step, index) =>
    ((walk: 'completed' | 'active' | 'upcoming') => ({
      step,
      index,
      walk,
      state: step.error === true ? ('error' as const) : walk,
    }))(index < activeIndex ? 'completed' : index === activeIndex ? 'active' : 'upcoming'),
  ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Stepper',
    element: () => root,
    state: () => ({
      'active-index': activeIndex,
      steps: rows.map((row) => ({ label: row.step.label, state: row.state })),
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!listening.stepSelect) throw new Error('These steps are not revisitable.')
            if (!Number.isInteger(value) || value < 0 || value >= activeIndex) {
              throw new Error(`Step ${value} is not a completed step, so it cannot be revisited.`)
            }
            onStepSelect?.(value)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<ol bind:this={root} class={styles.root} data-orientation={orientation} data-member="stepper"
    >{#each rows as row (row.index)
      }<li
        class={styles.step}
        data-state={row.state}
        data-interactive={(row.walk === 'completed' && listening.stepSelect) ? '' : undefined}
        aria-current={(row.walk === 'active') ? 'step' : undefined}
        ><svelte:element
          this={(row.walk === 'completed' && listening.stepSelect) ? 'button' : 'span'}
          class={styles.control}
          type={(row.walk === 'completed' && listening.stepSelect) ? 'button' : undefined}
          onclick={() => { if (row.walk === 'completed' && listening.stepSelect) onStepSelect?.(row.index) }}
          ><span class={styles.indicator} aria-hidden="true"
            >{#if row.state === 'error'
              }<Icon name="error" size="sm"
            />{:else if row.state === 'completed'
              }<span class={styles.check}><Icon name="confirm" size="sm" /></span
            >{:else
              }{row.index + 1
            }{/if
          }</span
          ><span class={styles.copy}
            ><span class={styles.label}>{row.step.label}</span
            >{#if row.step.description !== undefined
              }<span class={styles.description}>{row.step.description}</span
            >{/if
            }<span class={styles.spoken}
              >{`, ${spoken({ position: row.index + 1, count: steps.length, state: row.state })}`
            }</span
          ></span
        ></svelte:element
        >{#if row.index !== steps.length - 1
          }<span class={styles.connector} data-filled={(row.walk === 'completed') ? '' : undefined}></span
        >{/if
      }</li
    >{/each
  }</ol
>{/if
}{@render joined.end?.()}
